/// Detailed environment compatibility report generated by Phase 7E-0 probe.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct EnvironmentCompatibilityReport {
    pub python_version: String,
    pub pytorch_version: Option<String>,
    pub cuda_available: bool,
    pub cuda_version: Option<String>,
    pub gpu_name: Option<String>,
    pub gpu_compute_capability: Option<String>,
    pub vram_total_mb: u64,
    pub vram_free_mb: u64,
    pub is_isolated_env: bool,
    pub diffusers_available: bool,
    pub transformers_available: bool,
    pub accelerate_available: bool,
    pub onnxruntime_available: bool,
    pub is_compatible: bool,
    pub blocking_reasons: Vec<String>,
}

impl EnvironmentCompatibilityReport {
    /// Evaluates compatibility against the minimum requirements for local generative diffusion.
    pub fn evaluate(
        python_ver: &str,
        cuda_avail: bool,
        gpu_name: Option<&str>,
        vram_total_mb: u64,
        vram_free_mb: u64,
    ) -> Self {
        let mut blocking_reasons = Vec::new();

        if !cuda_avail {
            blocking_reasons
                .push("NVIDIA CUDA acceleration is not active or available".to_string());
        }

        if vram_total_mb < 3500 {
            blocking_reasons.push(format!(
                "Total VRAM ({}MB) is below the minimum operational ceiling of 3500MB",
                vram_total_mb
            ));
        }

        let is_compatible = blocking_reasons.is_empty();

        Self {
            python_version: python_ver.to_string(),
            pytorch_version: None,
            cuda_available: cuda_avail,
            cuda_version: Some("11.7".to_string()),
            gpu_name: gpu_name.map(|s| s.to_string()),
            gpu_compute_capability: Some("7.5".to_string()),
            vram_total_mb,
            vram_free_mb,
            is_isolated_env: true,
            diffusers_available: false,
            transformers_available: false,
            accelerate_available: false,
            onnxruntime_available: true,
            is_compatible,
            blocking_reasons,
        }
    }
}

