/// Standardized neural model roles for Phase 7G production video synthesis.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub enum ModelRole {
    Sd15Base,
    AnimateDiffMotion,
    PoseControl,
    DepthControl,
    IpAdapterFace,
    ClipVision,
}

impl ModelRole {
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Sd15Base => "sd15_base",
            Self::AnimateDiffMotion => "animatediff_motion",
            Self::PoseControl => "pose_control",
            Self::DepthControl => "depth_control",
            Self::IpAdapterFace => "ip_adapter_face",
            Self::ClipVision => "clip_vision",
        }
    }
}

/// Inventory record for a single model artifact.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct ModelInventoryEntry {
    pub name: String,
    pub role: ModelRole,
    pub path: PathBuf,
    pub size_bytes: u64,
    pub format: String,
    pub sha256: Option<String>,
    pub compatibility_status: String,
    pub present: bool,
    pub loaded: bool,
    pub inference_used: bool,
}

/// Production model discovery and inventory manager for Phase 7G.
pub struct ProductionModelInventory;

impl ProductionModelInventory {
    /// Scans a root model directory for production models and categorizes them by role.
    pub fn scan_and_discover(models_root: &Path) -> Vec<ModelInventoryEntry> {
        let mut entries = Vec::new();
        let expected_roles = vec![
            (
                "v1-5-pruned-emaonly.safetensors",
                "Stable Diffusion 1.5",
                ModelRole::Sd15Base,
                "safetensors",
            ),
            (
                "v3_sd15_mm.ckpt",
                "AnimateDiff v3 Motion Module",
                ModelRole::AnimateDiffMotion,
                "ckpt",
            ),
            (
                "control_v11p_sd15_openpose.safetensors",
                "OpenPose / DWPose ControlNet",
                ModelRole::PoseControl,
                "safetensors",
            ),
            (
                "control_v11f1p_sd15_depth.safetensors",
                "Depth ControlNet",
                ModelRole::DepthControl,
                "safetensors",
            ),
            (
                "ip-adapter-plus-face_sd15.safetensors",
                "IP-Adapter Face Plus",
                ModelRole::IpAdapterFace,
                "safetensors",
            ),
            (
                "model.safetensors",
                "CLIP ViT-H/14 Vision Encoder",
                ModelRole::ClipVision,
                "safetensors",
            ),
        ];

        for (filename, name, role, format) in expected_roles {
            let path = models_root.join(filename);
            let present = path.exists();
            let size_bytes = if present {
                std::fs::metadata(&path).map(|m| m.len()).unwrap_or(0)
            } else {
                0
            };
            let sha256 = if present {
                compute_sha256(&path).ok()
            } else {
                None
            };

            entries.push(ModelInventoryEntry {
                name: name.to_string(),
                role,
                path,
                size_bytes,
                format: format.to_string(),
                sha256,
                compatibility_status: if present {
                    "COMPATIBLE".to_string()
                } else {
                    "ABSENT".to_string()
                },
                present,
                loaded: false,
                inference_used: false,
            });
        }

        entries
    }
}

/// Authoritative execution classification for Phase 8.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum Phase8ExecutionClassification {
    RealProductionVideoAccepted,
    RealInferencePartiallyCompleted,
    ProductionModelUnavailable,
    ProductionModelHardwareBlocked,
    ProductionModelCompatibilityFailed,
    ProductionModelInferenceFailed,
}

impl Phase8ExecutionClassification {
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::RealProductionVideoAccepted => "REAL_PRODUCTION_VIDEO_ACCEPTED",
            Self::RealInferencePartiallyCompleted => "REAL_INFERENCE_PARTIALLY_COMPLETED",
            Self::ProductionModelUnavailable => "PRODUCTION_MODEL_UNAVAILABLE",
            Self::ProductionModelHardwareBlocked => "PRODUCTION_MODEL_HARDWARE_BLOCKED",
            Self::ProductionModelCompatibilityFailed => "PRODUCTION_MODEL_COMPATIBILITY_FAILED",
            Self::ProductionModelInferenceFailed => "PRODUCTION_MODEL_INFERENCE_FAILED",
        }
    }
}

/// Physical artifact verification status for Phase 8 execution outputs.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Default)]
#[serde(rename_all = "camelCase")]
pub struct Phase8ArtifactInventory {
    pub sd15_smoke_test_png: Option<PathBuf>,
    pub animatediff_4frame_dir: Option<PathBuf>,
    pub animatediff_8frame_dir: Option<PathBuf>,
    pub level_c_1s_mp4: Option<PathBuf>,
    pub level_d_3s_mp4: Option<PathBuf>,
    pub level_e_full_mp4: Option<PathBuf>,
    pub generation_metadata_json: Option<PathBuf>,
}

impl Phase8ArtifactInventory {
    /// Inspects an output root directory to detect which physical artifacts actually exist.
    pub fn discover_artifacts(output_root: &Path) -> Self {
        let sd15 = output_root.join("sd15_smoke").join("output.png");
        let a4 = output_root.join("animatediff_4");
        let a8 = output_root.join("animatediff_8");
        let c1s = output_root.join("level_c_1s").join("output.mp4");
        let d3s = output_root.join("level_d_3s").join("output.mp4");
        let e_full = output_root.join("level_e_full").join("output.mp4");
        let meta = output_root.join("final_generation_metadata.json");

        Self {
            sd15_smoke_test_png: if sd15.exists() { Some(sd15) } else { None },
            animatediff_4frame_dir: if a4.exists() { Some(a4) } else { None },
            animatediff_8frame_dir: if a8.exists() { Some(a8) } else { None },
            level_c_1s_mp4: if c1s.exists() { Some(c1s) } else { None },
            level_d_3s_mp4: if d3s.exists() { Some(d3s) } else { None },
            level_e_full_mp4: if e_full.exists() { Some(e_full) } else { None },
            generation_metadata_json: if meta.exists() { Some(meta) } else { None },
        }
    }

    /// Evaluates execution classification based on existing physical artifacts.
    pub fn classify(
        &self,
        model_available: bool,
        hardware_compatible: bool,
    ) -> Phase8ExecutionClassification {
        if !model_available {
            return Phase8ExecutionClassification::ProductionModelUnavailable;
        }
        if !hardware_compatible {
            return Phase8ExecutionClassification::ProductionModelHardwareBlocked;
        }
        if self.level_e_full_mp4.is_some() {
            Phase8ExecutionClassification::RealProductionVideoAccepted
        } else if self.sd15_smoke_test_png.is_some() || self.level_d_3s_mp4.is_some() {
            Phase8ExecutionClassification::RealInferencePartiallyCompleted
        } else {
            Phase8ExecutionClassification::ProductionModelUnavailable
        }
    }
}

